sec('data','03 · 数据与划分',p('扫描29228数组=14614原始+镜像；镜像不作为独立样本。选取走路/站立上肢相关类别的全部候选，无top-N上限；不是整个HumanML3D所有类别。源NPY：'+str(D/'humanml3d_rebuild/staging-v1/HumanML3D/new_joints')+'；文本与官方划分在 /root/gpufree-data/datasets/HumanML3D-official/HumanML3D。')+table(['阶段','规则'],[['文本','优先walk/march/pace；否则arm/hand/wave/gesture/clap/point/salute或stand/stationary/idle归站立上肢。合并所有描述后判断。'],['排除','跑跳、舞蹈、坐蹲跪爬躺、踢拳、楼梯/椅子/游泳等关键词；混合描述可能被整体排除。'],['数组','[T,22,3]，至少40帧，数值有限，源20Hz。'],['站立几何','根水平路径≤.30m，高度变化≤.12m，脚水平跨度≤.20m。'],['来源隔离','沿用官方划分；去掉410条与val/test原始录制来源相同的train片段。未额外证明val/test彼此来源隔离。'],['候选','5900：train3090/1548、val218/100、test644/300（走路/站立）。'],['膝弯曲','standing_upper双膝角集合p90≤40°；排除126条，5774条送重定向。不是每帧直立保证。'],['最终','质量/FK后5361条；实际划分如下。']])+table(['集合','走路','站立','总数','参考帧数'],[[k,v['counts']['walking'],v['counts']['standing_upper'],sum(v['counts'].values()),v['frames']] for k,v in summary.items()])+p('训练4209条、4981348帧=约27.67小时处理后50Hz参考，含减速拉伸，不能当作原始录制总时长。标签为启发式，可能误分或漏掉动作。'),'类别覆盖、过滤规则、来源隔离是否足够？')
sec('retarget','04 · 重定向与几何',p('采用指定tw_retargeting原生C++ QP方法：stream模式、iterations=1、原生90Hz输出，再线性重采样50Hz。求解器几何从修正后urdf0711_training_30dof.urdf派生；关节限位与肢段长度来自训练模型，修正chest坐标框架和任务朝向，保留原方法。')+p('q_training=sign×q_native+offset；28求解器关节映射30自由度，两侧foot_roll参考为0。坐标契约tw44_table_v2。派生模型100随机姿态FK矩阵等价误差记录为0；这不是人体重定向零误差。QP KKT残差需有限且≤1e-6。')+pre(read(N/'configs/selected_head_axis.json'))+p('上述position-scale/posture-bias/acceleration-cost是离线重定向参数，不是RL奖励。mean-distance-mm=5不是全部动作通过5mm认证。完整原生实现与映射表见附录。'),'几何、零位、坐标与重定向目标权重是否正确？')
sec('reference','05 · 参考数据处理',p('源[x,y,z]转机器人[z,x,y]，初始髋横向对齐−Y并保留后续转向。根相对第一帧平移缩放0.28963，名义高度0.28m；双髋方向恢复yaw，根参考未恢复完整roll/pitch。28→30映射后按URDF限位裁剪并记录比例；本轮要求clipped_fraction=0。')+pre('s=max(1, joint_p99_ratio/.9, joint_peak_ratio/1.2, root_xy_p99/.6, root_xy_peak/.8, root_yaw_p99/2, root_yaw_peak/3)')+p('每片时间拉伸最多6倍，超过需求上限则质量失败。关节、根平移、展开的yaw同步线性插值，输出50Hz，再求新时间轴导数。控制50Hz不表示人体原速；本轮没有逐渐加速课程。'),'根缩放、倾斜简化和动作节奏是否合理？')
sec('quality','06 · 质量门槛与FK',table(['检查','实际规则'],[['近限位','距边界≤max(.001rad,关节范围1%)；任一关节占比>5%或连续>.25s为严格失败。'],['关节速度','超速元素占比≤.5%，每关节p99速度比例≤1，峰值≤1.2。'],['根速度','水平p99≤.6、峰值≤.8m/s；yaw p99≤2、峰值≤3rad/s。'],['当前例外政策','用户视觉审阅后仅near_limit_fraction/run允许提示，保留strict_quality_pass、原始原因及acceptance_policy。按本轮政策quality_pass不等于原严格全通过。'],['FK','Isaac写入参考状态、批量128求身体位姿速度，非动力学接触验证。'],['地面','以整段双脚碰撞包围角点最低值计算一个固定Z偏移，使最低处=1mm；非逐帧贴地，仍可能悬空或滑脚。'],['FK门槛','base/root状态误差≤1e-5；速度与差分的一致性p95线速度≤.05m/s，角速度≤.2rad/s。']])+p('政策tw75_user_review_20261003_near_limits_advisory。FK batch1与128关节角速度相同、身体位置最大差1.62e-6m；启动记录83项测试通过。门槛不保证完整支撑时序或语义正确。'),'哪些质量提示需要收紧？')
sec('sampling','07 · 采样与episode',p('类别重置先验走路/站立各50%，类内片段等权；weight=.5/类片段数/(frames−1)，抵消长片段起始帧数偏置。adaptive_uniform_ratio=1，本轮不混失败驱动采样。')+p('随机片段、随机起始帧，用参考根/关节状态初始化再加扰动。参考每策略步前进1帧；片尾终止重置，不无缝接另一个动作。训练episode上限30秒，runner初始episode长度随机化。50/50是重置概率，不保证实际帧数或时间占比各半。curriculum=None，固定混合训练。'),'需不需要类内困难样本、完整起步或动作切换？')
sec('physics','08 · 动力学与执行器',p('30自由度浮动基座、平地重力接触、convex_hull碰撞、自碰撞关闭、固定关节合并；位置/速度求解迭代8/4。质量取URDF约0.841kg；资产初始Z=.264m，episode重置由参考覆盖。电机未选定，以下是仿真假设。')+table(['组','Kp','Kd','力矩N·m','速度rad/s','armature','动作尺度rad'],[['主要腿含ankle_yaw',20,1,40,3,.001,.5],['ankle_pitch/foot_roll',10,.5,15,3,.001,.375],['腰',10,.5,20,2,.001,.5],['臂',5,.25,8,2,.0005,.4],['颈',3,.15,3,2,.0002,.25]])+p('ImplicitActuator由物理引擎执行PD，无指定电机电流环、热限制、真实力矩转速曲线或通信延迟。地面静/动摩擦1/1、multiply组合；soft_joint_pos_limit_factor=1。USD force_usd_conversion=False允许缓存，URDF哈希不等于重新认证已加载USD。'),'电机假设、自碰撞关闭与碰撞体是否合适？')
sec('control','09 · 控制频率与动作',p('物理dt=.005s=200Hz，decimation4；策略/观测/目标50Hz，目标保持4物理步。不是硬件电流环频率。')+pre('q_raw = default_joint_position + action_scale * action\ndelta = clamp(q_raw-q_previous_target, ±velocity_limit*.02*.5)\nq_target = q_previous_target + delta\nPD + physics -> actual state')+p('tau=0无指数低通，目标变化率限制启用；腿/脚每步最多.03rad，腰/臂/颈.02rad，即1.5/1rad/s。不是实际速度保证或参考统一减半。重置记忆从实际角初始化。动作相对默认姿态，不是参考角残差；clip_actions=null，变化率限制不等于绝对幅度裁剪。'),'目标限速是否压制拟人快速动作？')
