css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f3f5f8;color:#172738;font:16px/1.8 system-ui,"Microsoft YaHei",sans-serif}nav{position:fixed;width:260px;height:100vh;overflow:auto;background:#112e3d;color:#e4eef3;padding:24px 18px}nav a{display:block;color:#d3e4ea;text-decoration:none;padding:7px 0;font-size:14px}nav a:hover{color:#71e1c5}main{max-width:1300px;margin-left:260px;padding:40px 48px}header{padding:24px 0 32px;border-bottom:3px solid #168776}h1{font-size:36px;line-height:1.35;margin:12px 0}h2{font-size:24px;color:#146c61}section{background:white;padding:28px 32px;margin:24px 0;border:1px solid #dce3e9;border-radius:12px;scroll-margin-top:16px}p{overflow-wrap:anywhere}code{font:13px/1.6 monospace;background:#edf3f6;overflow-wrap:anywhere}pre{font:12px/1.65 monospace;background:#102632;color:#e1f2f3;padding:16px;overflow:auto;max-height:650px;tab-size:4}.table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:10px 12px;text-align:left;vertical-align:top;border-bottom:1px solid #dce3e9;min-width:85px}th{background:#e9f4f1}tr:nth-child(even){background:#f7f9fa}.review{margin-top:24px;border-top:1px dashed #b6c6cd;padding-top:16px}.review p{font-size:14px;color:#596b76}textarea{width:100%;min-height:80px;border:1px solid #b9c9d1;border-radius:6px;padding:12px;font:inherit}button{background:#146c61;color:white;border:0;border-radius:6px;padding:10px 16px;cursor:pointer}details{margin:12px 0;border:1px solid #dce3e9;padding:10px}summary{cursor:pointer;overflow-wrap:anywhere;font-size:14px}.meta{font-size:13px;color:#586c78}input[type=search]{width:100%;padding:10px;border-radius:6px;border:0;margin:16px 0}@media(max-width:900px){nav{position:static;width:auto;height:auto}nav .links{display:grid;grid-template-columns:1fr 1fr}main{margin:0;padding:20px}section{padding:20px}h1{font-size:28px}}@media print{nav,button,.review{display:none}main{margin:0;padding:0}body{background:white}section{border:0;padding:10px 0}pre{max-height:none;white-space:pre-wrap;overflow-wrap:anywhere;color:black;background:#eee}.table{overflow:visible}h2{break-after:avoid}}'''
nav=''.join('<a href="#'+k+'">'+esc(t)+'</a>' for k,t,_,_ in sections)
body=''.join('<section id="'+k+'"><h2>'+esc(t)+'</h2>'+b+'<div class="review"><label><input type="checkbox" data-key="'+k+'-done"> 已审阅</label><p>'+esc(q)+'</p><textarea aria-label="'+esc(t)+'审阅意见" data-key="'+k+'-note" placeholder="记录疑问、建议与优先级"></textarea></div></section>' for k,t,b,q in sections)
js='''const fields=[...document.querySelectorAll('[data-key]')],prefix='tw81-review-v1:';let storageOK=true;for(const el of fields){try{const v=localStorage.getItem(prefix+el.dataset.key);if(el.type==='checkbox')el.checked=v==='true';else el.value=v||''}catch(e){storageOK=false}el.addEventListener('input',()=>{try{localStorage.setItem(prefix+el.dataset.key,el.type==='checkbox'?el.checked:el.value)}catch(e){storageOK=false}progress()})}function progress(){document.getElementById('progress').textContent='已审阅 '+fields.filter(x=>x.type==='checkbox'&&x.checked).length+' / 16 节'+(storageOK?'':'；浏览器无法保存，请及时导出。')}progress();document.getElementById('export').onclick=()=>{const data={issue:'TW-81',exported_at:new Date().toISOString(),review:Object.fromEntries(fields.map(e=>[e.dataset.key,e.type==='checkbox'?e.checked:e.value]))};const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='TW-81-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};document.getElementById('search').oninput=e=>{const q=e.target.value.trim().toLowerCase();for(const s of document.querySelectorAll('main section'))s.hidden=Boolean(q&&!s.textContent.toLowerCase().includes(q))};'''
intro=p('审阅勾选与意见仅保存在当前浏览器localStorage。地址或浏览器变化可能导致记录不可见，请及时导出JSON。不自动写入Linear或更改训练。')+'<button id="export">导出审阅意见 JSON</button> <button onclick="window.print()">打印 / 保存 PDF</button><p id="progress" aria-live="polite"></p>'
